import{_ as t,o as a,c as s,X as i}from"./chunks/framework.Bo638KvF.js";const u=JSON.parse('{"title":"Training DataLoader API","titleTemplate":":title · PyCellPack","description":"","frontmatter":{"outline":2},"headers":[],"relativePath":"python/api/dataloader.md","filePath":"python/api/dataloader.md"}'),d={name:"python/api/dataloader.md"};function o(r,e,n,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="training-dataloader-api" tabindex="-1">Training DataLoader API <a class="header-anchor" href="#training-dataloader-api" aria-label="Permalink to &quot;Training DataLoader API&quot;">​</a></h1><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pycellpack </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Accesses, ScDataset, ScDataLoader</span></span></code></pre></div><p>These interfaces produce owned Tensor batches from corpus-local sample orders. For a complete program and checked output, read <a href="/CellPack/python/docs/dataloader.html">training batches</a>. For NumPy ring views and global cell IDs, use the separate <a href="/CellPack/python/api/loader.html">native Loader</a>.</p><h2 id="dataset-and-sample-declarations" tabindex="-1">Dataset and sample declarations <a class="header-anchor" href="#dataset-and-sample-declarations" aria-label="Permalink to &quot;Dataset and sample declarations&quot;">​</a></h2><h3 id="scdataset" tabindex="-1">ScDataset <a class="header-anchor" href="#scdataset" aria-label="Permalink to &quot;ScDataset&quot;">​</a></h3><p><code>ScDataset(store, *, ids)</code> pairs a <strong>2-D file-backed Store view</strong> with one standard ID per visible column. It keeps the Store and copies the ID map to read-only uint32 storage. Keep the backing file immutable while using the loader.</p><table tabindex="0"><thead><tr><th>Input</th><th>Requirement</th></tr></thead><tbody><tr><td><code>store</code></td><td>Its decode dtype equals its file dtype; memory streams are rejected</td></tr><tr><td><code>ids</code></td><td>One-dimensional NumPy integer array of length <code>store.shape[1]</code></td></tr><tr><td>Kept IDs</td><td>Distinct integers in <code>[0, uint32.max)</code> within this dataset</td></tr><tr><td>Dropped columns</td><td><code>-1</code> or <code>uint32.max</code></td></tr><tr><td>Store views</td><td>Row selection and ordinary column subsets/reordering remain lazy; one stored column cannot contribute multiple kept dimensions</td></tr></tbody></table><p>Rows in sample orders address this view. For <code>store[[5, 2]]</code>, local row <code>0</code> means stored row <code>5</code>. Choose output conversion on ScDataLoader rather than with <code>Store.astype</code>. <code>ScDataset.from_anndata(adata, ids=..., layer=None)</code> selects an existing Store from <code>X</code> or a named layer; it does not encode arrays or match names.</p><h3 id="corpus-accesses" tabindex="-1">Corpus Accesses <a class="header-anchor" href="#corpus-accesses" aria-label="Permalink to &quot;Corpus Accesses&quot;">​</a></h3><p><code>Accesses(dataset_ids, rows)</code> borrows two parallel 1-D NumPy integer arrays. The value object does not validate their contents. Starting an iterator copies them to uint32 dataset IDs and uint64 local rows, checks equal lengths and nonnegative ranges, and validates each pair against the corpus. Repeats and order are retained. The corpus&#39;s total contributed rows must fit uint32 CellIds.</p><p><code>len(accesses)</code> counts <strong>samples</strong>. This is the package-root Accesses, distinct from <a href="/CellPack/python/api/access-functions.html">native <code>loader.Accesses</code></a>, whose values are global cell IDs. ScDataLoader also accepts the tuple <code>(dataset_ids, rows)</code>.</p><h2 id="construct-a-loader" tabindex="-1">Construct a loader <a class="header-anchor" href="#construct-a-loader" aria-label="Permalink to &quot;Construct a loader&quot;">​</a></h2><h3 id="sampling-and-output" tabindex="-1">Sampling and output <a class="header-anchor" href="#sampling-and-output" aria-label="Permalink to &quot;Sampling and output&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Contract</th></tr></thead><tbody><tr><td><code>corpus</code></td><td>Required</td><td>Nonempty sequence of ScDataset objects; captured as a tuple</td></tr><tr><td><code>accesses</code></td><td><code>None</code></td><td>Corpus Accesses or its two-array tuple</td></tr><tr><td><code>access_fn</code></td><td><code>None</code></td><td>Native AccessFn; corpus counts are bound automatically; supply exactly one of accesses/access_fn</td></tr><tr><td><code>out_ids</code></td><td><code>None</code></td><td>Nonempty distinct standard IDs below <code>uint32.max</code>, in output order; omission requires identical dataset maps and selects their kept IDs</td></tr><tr><td><code>process</code></td><td><code>None</code></td><td>ProcessFn with declared OutputLayout; omission produces dense <code>X</code></td></tr><tr><td><code>dtype</code></td><td><code>None</code></td><td>float32, or the ProcessFn&#39;s required input dtype; must be a supported native loader conversion</td></tr><tr><td><code>default</code></td><td><code>0</code></td><td>Typed fill for dimensions absent from a source; does not replace present sparse zeros</td></tr><tr><td><code>drop_last</code></td><td><code>False</code></td><td>Trim incomplete final batch before execution</td></tr></tbody></table><p>Preset token/configuration tables follow <code>out_ids</code> order. They do not use standard IDs as table offsets. Output fields with a process are declared by its <a href="/CellPack/python/api/process-functions.html">OutputLayout</a>.</p><h3 id="execution-and-memory" tabindex="-1">Execution and memory <a class="header-anchor" href="#execution-and-memory" aria-label="Permalink to &quot;Execution and memory&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Unit / contract</th></tr></thead><tbody><tr><td><code>batch_size</code></td><td><code>256</code></td><td>Positive samples per output slot; bool is rejected</td></tr><tr><td><code>prefetch</code></td><td><code>4</code></td><td>Positive host output slots; bool is rejected</td></tr><tr><td><code>workers</code></td><td><code>None</code></td><td>Native threads; automatic value is <code>min(16, usable CPUs)</code>; explicit values bypass this automatic cap</td></tr><tr><td><code>cache_bytes</code></td><td><code>0</code></td><td>Nonnegative online input-cache budget; zero disables planning</td></tr><tr><td><code>scratch_bytes</code></td><td><code>0</code></td><td>Process scratch bytes per worker</td></tr><tr><td><code>backend</code></td><td><code>None</code></td><td>Probe io_uring, else pread; explicit <code>&quot;uring&quot;</code> or <code>&quot;pread&quot;</code></td></tr><tr><td><code>direct_io</code></td><td><code>None</code></td><td>Probe O_DIRECT; <code>False</code> forces buffered input I/O</td></tr><tr><td><code>**settings</code></td><td>Empty</td><td>Individual LoaderConfig fields such as inflight, claim_batch, window, profile and cpus; config and slot_rows are rejected</td></tr></tbody></table><p>Output prefetch, input cache and returned Tensor allocations are separate budgets. ScDataLoader derives native <code>slot_rows</code> from <code>batch_size</code>.</p><h3 id="tensor-delivery" tabindex="-1">Tensor delivery <a class="header-anchor" href="#tensor-delivery" aria-label="Permalink to &quot;Tensor delivery&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Contract</th></tr></thead><tbody><tr><td><code>device</code></td><td><code>&quot;cpu&quot;</code></td><td>CPU or CUDA PyTorch device, for example <code>&quot;cuda:0&quot;</code></td></tr><tr><td><code>contiguous</code></td><td><code>False</code></td><td>True for all output fields, a field name or a sequence for selected fields; unknown names are rejected</td></tr></tbody></table><p>Iteration returns <code>dict[str, torch.Tensor]</code>. Built-in <code>X</code> has shape <code>(actual_batch_rows, len(out_ids))</code>; process field shapes have batch rows prefixed. CPU outputs own a packed clone and may be retained without holding native ring slots. CUDA outputs own device storage after one packed H2D transfer. The copy stream completes before host views are released. Field views may be strided; selected fields or misaligned field layouts can require copies. Device field-copy streams establish dependencies with the current CUDA stream before return.</p><h2 id="iteration-epochs-and-completion" tabindex="-1">Iteration, epochs and completion <a class="header-anchor" href="#iteration-epochs-and-completion" aria-label="Permalink to &quot;Iteration, epochs and completion&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Behavior</th></tr></thead><tbody><tr><td><code>len(loading)</code></td><td>Batch count for the current order; does not start workers, import Torch or validate sample bounds</td></tr><tr><td><code>iter(loading)</code></td><td>Copies/validates an array order or binds its AccessFn, imports Torch, creates a fresh ring/run and resets stats to None</td></tr><tr><td><code>loading.out_ids</code></td><td>Read-only output-panel view</td></tr><tr><td><code>loading.stats</code></td><td>None before the first run or during a new run; final RunStats on exhaustion, progress snapshot after early close</td></tr><tr><td><code>loading.close()</code></td><td>Closes the active iterator; another run can be started afterward</td></tr><tr><td><code>with loading:</code></td><td>Closes the active iterator on exit, including break and exception paths</td></tr></tbody></table><p>Only one iterator may be active. The caller owns epoch policy: replace <code>loading.accesses</code> or <code>loading.access_fn</code> <strong>between</strong> runs. Every iterator starts from the beginning of that supplied order; there is no implicit reshuffle or resume offset. Use a sliced order to resume. Do not mutate corpus or output configuration after construction.</p><h2 id="failures-and-validation-timing" tabindex="-1">Failures and validation timing <a class="header-anchor" href="#failures-and-validation-timing" aria-label="Permalink to &quot;Failures and validation timing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure</th><th>Where to look</th></tr></thead><tbody><tr><td><code>TypeError</code> / <code>ValueError</code> during construction</td><td>Corpus, Store, ID maps, panel, process output declaration or execution settings</td></tr><tr><td><code>TypeError</code> / <code>ValueError</code> on iterator start</td><td>Sample array shapes/types, dataset indices or dataset-local rows</td></tr><tr><td><code>RuntimeError</code> for a second iterator</td><td>Exhaust or close the active iterator first</td></tr><tr><td><code>ModuleNotFoundError</code> naming torch</td><td>Install PyTorch separately before iteration</td></tr><tr><td>I/O or native worker error during iteration</td><td>Source file state, backend, process callback and native error cause</td></tr></tbody></table><p>Completed Tensor batches retain independent storage after early close. A progress snapshot is not a success receipt for the full order; only normal exhaustion collects the final statistics.</p><h2 id="declarations" tabindex="-1">Declarations <a class="header-anchor" href="#declarations" aria-label="Permalink to &quot;Declarations&quot;">​</a></h2><details class="details custom-block"><summary>Complete declarations and members</summary><h3 id="scdataset-1" tabindex="-1">ScDataset <a class="header-anchor" href="#scdataset-1" aria-label="Permalink to &quot;ScDataset&quot;">​</a></h3><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ScDataset(store: Store, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ids: np.ndarray)</span></span></code></pre></div><p>A two-dimensional Store and one explicit standard id per visible dim.</p><p>ids must be a NumPy integer vector. -1/uint32.max drops a dim; other ids must be distinct. Rows address this Store&#39;s current view. Ordinary column subsets/reorderings stay lazy. Multiple mapped dims referring to the same stored column and dtype-converting Store views are rejected explicitly.</p><h4 id="scdataset-from-anndata" tabindex="-1">ScDataset.from_anndata <a class="header-anchor" href="#scdataset-from-anndata" aria-label="Permalink to &quot;ScDataset.from_anndata&quot;">​</a></h4><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ScDataset.from_anndata(adata, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ids: np.ndarray, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">layer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Select X (layer=None) or a layer already holding a Store.</p><p>This convenience imports no AnnData and never compresses a matrix implicitly. H5CP&#39;s read_h5(..., lazy=True) preserves these Stores.</p><h4 id="scdataset-store" tabindex="-1">ScDataset.store <a class="header-anchor" href="#scdataset-store" aria-label="Permalink to &quot;ScDataset.store&quot;">​</a></h4><p><code>store: Store</code> — property.</p><p>The immutable Store view supplied for this dataset.</p><h4 id="scdataset-ids" tabindex="-1">ScDataset.ids <a class="header-anchor" href="#scdataset-ids" aria-label="Permalink to &quot;ScDataset.ids&quot;">​</a></h4><p><code>ids: np.ndarray</code> — property.</p><p>Read-only uint32 standard IDs, one per visible column; uint32.max marks a dropped dimension.</p><h4 id="scdataset-shape" tabindex="-1">ScDataset.shape <a class="header-anchor" href="#scdataset-shape" aria-label="Permalink to &quot;ScDataset.shape&quot;">​</a></h4><p><code>shape</code> — property.</p><p>Visible (rows, columns) of the dataset view.</p><h4 id="scdataset-dtype" tabindex="-1">ScDataset.dtype <a class="header-anchor" href="#scdataset-dtype" aria-label="Permalink to &quot;ScDataset.dtype&quot;">​</a></h4><p><code>dtype</code> — property.</p><p>Stored numeric dtype. Loader output conversion is configured separately.</p><h3 id="accesses" tabindex="-1">Accesses <a class="header-anchor" href="#accesses" aria-label="Permalink to &quot;Accesses&quot;">​</a></h3><p>Parallel arrays of corpus dataset indices and dataset-local rows.</p><p>The caller owns ordering, sampling and epoch policy. Arrays are borrowed by this value object and snapshotted when a loader iterator starts.</p><h4 id="fields-and-defaults" tabindex="-1">Fields and defaults <a class="header-anchor" href="#fields-and-defaults" aria-label="Permalink to &quot;Fields and defaults&quot;">​</a></h4><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dataset_ids: np.ndarray</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rows: np.ndarray</span></span></code></pre></div><h3 id="scdataloader" tabindex="-1">ScDataLoader <a class="header-anchor" href="#scdataloader" aria-label="Permalink to &quot;ScDataLoader&quot;">​</a></h3><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ScDataLoader(corpus: Sequence[ScDataset], </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">accesses</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, access_fn: AccessFn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> None</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, out_ids: np.ndarray </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> None</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, process: ProcessFn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> None</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">batch_size</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">device</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;cpu&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">prefetch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">cache_bytes</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">workers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">dtype</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">default</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">scratch_bytes</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">drop_last</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">False</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">contiguous</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">False</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">direct_io</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">settings)</span></span></code></pre></div><p>Iterate named Tensors while native workers supply a bounded packed ring.</p><p>corpus is an ordered list of ScDatasets; dataset ids are its indices. accesses accepts Accesses or (dataset_ids, rows). Alternatively access_fn takes a native AccessFn. Supply exactly one; the caller owns sampling, ordering and epoch policy.</p><p>out_ids defines the common mapped panel, in ProcessFn table order. It can be omitted for datasets with identical standard ids. process outputs require a declared OutputLayout; without process the output is dense X. Torch is imported only by iteration, never by construction or len().</p><p>prefetch is the number of host output slots; workers are native threads. CUDA uses one packed H2D and returns field views; contiguous=True or a sequence of field names requests field copies on independent CUDA streams. CPU batches own their storage and may be retained without blocking a slot.</p><h4 id="scdataloader-out-ids" tabindex="-1">ScDataLoader.out_ids <a class="header-anchor" href="#scdataloader-out-ids" aria-label="Permalink to &quot;ScDataLoader.out_ids&quot;">​</a></h4><p><code>out_ids</code> — property.</p><p>Read-only standard IDs in model output order.</p><h4 id="scdataloader-close" tabindex="-1">ScDataLoader.close <a class="header-anchor" href="#scdataloader-close" aria-label="Permalink to &quot;ScDataLoader.close&quot;">​</a></h4><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ScDataLoader.close()</span></span></code></pre></div><p>Close this loader&#39;s active iterator; the loader can be reused.</p></details>`,29)])])}const k=t(d,[["render",o]]);export{u as __pageData,k as default};
